#if DEBUG
import Foundation

/// The Foundation Track as the showcase screenshots show it (owner, 2026-11-06: "show me every screen someone gets
/// when they go through the Foundation Track"). The content is REAL — the practice's rows exported from CM OS
/// (`ShowcaseTrackContent`, generated by `Scripts/showcase_track_fixture.py`) and decoded by the same wire types the
/// live backend uses — so every word on the screenshots is what a member reads. Only the member is invented: the
/// sample member "Marie", on the day the command line asks for, with the figures the server's rules would give her.
///
/// Arguments (with `-FAShowcase track`, `track-q`, `track-card`, `track-read` or `track-summary`):
///   -FATrackDay <1…15>      the member's day (15 = the two weeks are over); default 1
///   -FAPage <0…>            Home scrolled to that page of the day's card (`HomeView`'s pager); default 0
///   -FAQuestionnaire <id>   the questionnaire `track-q` opens over Home
///   -FAQStep intro|<screen>|done   the questionnaire step it opens on; default intro
///   -FACard <habit_bank id> -FAFace <face>   the action card `track-card` opens
///   -FASlug <slug>          the day's read `track-read` opens
enum ShowcaseTrack {
    enum QuestionnaireStep: Equatable {
        case intro
        case screen(Int)
        case done
    }

    // MARK: Arguments

    private static func arg(_ name: String) -> String? {
        let args = ProcessInfo.processInfo.arguments
        guard let i = args.firstIndex(of: name), i + 1 < args.count else { return nil }
        return args[i + 1]
    }

    /// True for every track scene: the backend then answers the track calls (and keeps Home a lead's Home).
    static var isOn: Bool {
        switch Showcase.screen {
        case .track?, .trackQuestionnaire?, .trackCard?, .trackRead?, .trackSummary?: true
        default: false
        }
    }

    static var day: Int { min(max(Int(arg("-FATrackDay") ?? "") ?? 1, 1), 15) }
    static var page: Int { max(Int(arg("-FAPage") ?? "") ?? 0, 0) }
    static var questionnaireId: String? { Showcase.screen == .trackQuestionnaire ? arg("-FAQuestionnaire") : nil }
    static var questionnaireStep: QuestionnaireStep {
        switch arg("-FAQStep") {
        case "done"?: .done
        case let raw? where Int(raw) != nil: .screen(Int(raw)!)
        default: .intro
        }
    }
    static var cardId: String { arg("-FACard") ?? "" }
    static var face: String { arg("-FAFace") ?? "standard" }
    static var slug: String { arg("-FASlug") ?? "" }

    // MARK: The practice's content (decoded exactly as the live backend decodes it)

    private static func data(_ text: String) -> Data { Data(text.utf8) }

    static let days: [TrackDay] = (try? TrackJSON.decode([TrackDayWire].self, from: data(ShowcaseTrackContent.days)).map(\.day)) ?? []

    static let questionnaires: [TrackQuestionnaire] = {
        guard var list = try? TrackJSON.decode([TrackQuestionnaireWire].self, from: data(ShowcaseTrackContent.questionnaires)).map(\.questionnaire),
              let questions = try? TrackJSON.decode([TrackQuestionWire].self, from: data(ShowcaseTrackContent.questions)) else { return [] }
        for i in list.indices {
            list[i].questions = questions.filter { $0.questionnaireId == list[i].id }.map(\.question)
        }
        return list.sorted { $0.day < $1.day }
    }()

    static let cards: [ActionCardRow] = (try? JSON.decoder.decode([ActionCardRow].self, from: data(ShowcaseTrackContent.cards))) ?? []

    private struct ReadRow: Decodable, Sendable { let slug: String; let title: String?; let body_md: String? }
    private static let reads: [ReadRow] = (try? JSONDecoder().decode([ReadRow].self, from: data(ShowcaseTrackContent.reads))) ?? []

    static func read(slug: String) -> LibraryGetRow? {
        guard let row = reads.first(where: { $0.slug == slug }) else { return nil }
        return LibraryGetRow(title: row.title, tags: nil, bodyMd: row.body_md, locked: false)
    }

    // MARK: The sample member on that day — figures by the server's own rules (`member_track_status`)

    /// Marie photographs about 86 % of the meals the rule expects; every module is in on its own day.
    static func status() -> TrackStatus {
        let d = day, days = 14
        let elapsed = min(d, days)
        var s = TrackStatus(state: .active)
        s.day = d
        s.days = days
        let counted = questionnaires.filter { $0.countsTowardReview }
        s.modulesTotal = counted.count
        s.modulesDone = counted.filter { $0.day < d }.count
        s.mealsExpected = 3 * max(elapsed - 1, 0)
        s.mealsLogged = Int((Double(s.mealsExpected) * 0.86).rounded(.down))
        s.mealsPct = s.mealsExpected > 0 ? Int((100.0 * Double(s.mealsLogged) / Double(s.mealsExpected)).rounded()) : nil
        s.reviewUnlocked = s.modulesTotal > 0 && s.modulesDone >= s.modulesTotal && s.mealsExpected > 0
            && Double(s.mealsLogged) >= 0.8 * Double(s.mealsExpected)
        // The column default of a lead's enrolment: day 3 · 20 min, day 14 · 20 min gated by the review rule.
        let unlocked = s.reviewUnlocked
        s.calls = [
            TrackCall(day: 3, minutes: 20, gated: false, open: d >= 3),
            TrackCall(day: 14, minutes: 20, gated: true, open: d >= 14 && unlocked),
        ]
        // The sample profile: 66 kg, female, about 1900 kcal → tdee ± 5 % per 50 kcal, 1.3–1.7 g/kg.
        s.energyKcalLow = 1800
        s.energyKcalHigh = 2000
        s.proteinGLow = 86
        s.proteinGHigh = 112
        return s
    }

    /// Every questionnaire of an earlier day is in. Today's is not (the member is about to answer it).
    static func responses() -> [TrackResponse] {
        questionnaires.filter { $0.day < day }.map { q in
            TrackResponse(id: "showcase-r-\(q.day)", questionnaireId: q.id, answers: sampleAnswers(q), submitted: true,
                          submittedAt: ShowcaseData.at(q.day - day, 20, 30), updatedAt: ShowcaseData.at(q.day - day, 20, 30))
        }
    }

    /// Today's morning actions are ticked (the screenshots are taken at 9:00); nothing else yet.
    static func activity() -> [TrackActivityItem] {
        guard let today = days.first(where: { $0.day == min(day, 14) }) else { return [] }
        return today.actions.filter { $0.moment == .morning && !$0.isNew }.map { TrackActivityItem(day: today.day, kind: .action, itemKey: $0.key) }
    }

    /// Plausible answers so that "You told us …" lines read like a real member's. Named keys first, otherwise the
    /// first option of a choice; free text, numbers and the device pages stay unanswered.
    private static func sampleAnswers(_ q: TrackQuestionnaire) -> [String: JSONValue] {
        let named: [String: JSONValue] = [
            "primary_goals": .array([.string("energy"), .string("sleep"), .string("focus")]),
            "wake_time_workdays": .string("06:45"),
            "work_schedule_type": .string("regular"),
            "work_movement": .string("sitting"),
            "meals_per_day": .string("3"),
            "lunch_time": .string("12:30"),
            "caffeine_per_day": .string("2"),
            "exercise_days_week": .string("2"),
            "movement_discomfort": .string("no"),
            "bedtime_workdays": .string("23:00"),
        ]
        var answers: [String: JSONValue] = [:]
        for question in q.questions {
            if let value = named[question.key] { answers[question.key] = value; continue }
            guard case .list(let options)? = question.options, let first = options.first else { continue }
            switch question.kind {
            case .single?: answers[question.key] = .string(first.value)
            case .multi?: answers[question.key] = .array([.string(first.value)])
            default: break
            }
        }
        return answers
    }

    // MARK: The approved day-7 summary (from day 8: the practitioner approved it the evening before)

    /// The fixed parts are built from the content exactly as CLINICAL builds them (the goals from day 1, the actions
    /// new on days 8–14, the two ranges). "What we learned" is the one part a model drafts for a real member and a
    /// practitioner approves; here it only restates Marie's sample answers, in plain words.
    static func summary() -> TrackSummary? {
        guard day >= 8 else { return nil }
        let week2: [JSONValue] = days.filter { $0.day >= 8 }.flatMap { d in
            d.actions.filter(\.isNew).map { a in
                JSONValue.object(["key": .string(a.key), "day": .number(Double(d.day)), "moment": .string(a.moment.rawValue),
                                  "title": .string(a.titleEn ?? a.key)])
            }
        }
        let content: JSONValue = .object([
            "version": .number(1), "audience": .string("member"), "language": .string("en"),
            "learned": .object([
                "context": .string("You work regular hours, mostly sitting, and wake around 06:45 on workdays."),
                "food": .string("Three meals a day, lunch around 12:30, two coffees. You photographed most of your meals this week."),
                "movement": .string("You exercise on two days a week, and nothing is uncomfortable when you move."),
                "sleep": .string("You go to bed around 23:00 on workdays."),
                "stress": .string("You told us the week was busy at work."),
            ]),
            "goals": .object(["source": .string("day1"), "items": .array([
                .object(["value": .string("energy"), "label": .string("More energy")]),
                .object(["value": .string("sleep"), "label": .string("Better sleep")]),
                .object(["value": .string("focus"), "label": .string("Focus and clarity")]),
            ])]),
            "week2_actions": .array(week2),
            "energy_kcal": .object(["low": .number(1800), "high": .number(2000)]),
            "protein_g": .object(["low": .number(86), "high": .number(112)]),
        ])
        let row: JSONValue = .object(["id": .string("showcase-summary"), "day": .number(7), "content": content,
                                      "approved_at": .string(ISO8601.string(ShowcaseData.at(7 - day, 18)))])
        guard let encoded = try? JSONEncoder().encode(row) else { return nil }
        return (try? TrackJSON.decode(TrackSummaryWire.self, from: encoded))?.summary
    }
}
#endif
